    "notes": "斤 (jīn) ist die traditionelle Gewichtseinheit, auf dem chinesischen Festland genau 500 Gramm. Auf Märkten wird fast alles pro 斤 verkauft: 多少钱一斤？ Ein Kilogramm ist 公斤 (gōngjīn) = 两斤. Vor 斤 steht meist 两: 两斤苹果; umgangssprachlich, besonders im Norden, hört man aber auch 二斤. 半斤 ist ein halbes Jin. Auch das Körpergewicht wird oft in 斤 angegeben.",
